def compute(vars):
    shares_nov = vars["v1"]
    shares_dec = vars["v2"]
    total_shares = shares_nov + shares_dec
    return {
        "value": total_shares,
        "trace": {
            "shares_nov": shares_nov,
            "shares_dec": shares_dec,
            "total_shares": total_shares,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "shares"
            }
        }
    }
